  wahl:[{id:'w', t:'Bewertung des Ist-Ergebnisses:', opts:['Die Kreation arbeitet trotz geringerer Auslastung noch mit Gewinn.', 'Die Kreation macht Verlust – die Selbstkosten sind nicht mehr gedeckt.'], r:'fs@1 * sa@1 >= sk@1 ? 0 : 1'}],
